 if(event.type==='change'){persist();return;}
 if(event.type==='cue'){if(/pickup|place|ring/.test(event.name))character?.trigger('Resonance');audio.playWorldCue(event.name,event.position||position);return;}
 if(event.type==='message'){toast(event.text);return;}
 if(event.type==='discovery'){$('travel-feedback').hidden=true;experience?.showDiscovery(event);const cues={root:'v5_roots_hint',light:'v5_jade_hint',water:'v5_water_hint',flight:'v5_flight_hint',sun:'v5_final_hint'};if(cues[event.id]&&(event.id!=='sun'||adventure.snapshot().stages.slice(0,4).every(s=>s.done)))audio.speak(cues[event.id]);else if(event.id?.startsWith('feather-'))audio.speak('v5_feather');return;}
 if(event.type==='stage'){$('travel-feedback').hidden=true;playMoment({...event,focus:adventure.snapshot().stages.find(s=>s.id===event.id)?.position});audio.playMoment?.(event.id);character?.trigger('Resonance');state.collected.add(event.relicId);resonanceBurst?.trigger(time,position,3);audio.playWorldCue('stage',position);const cues={root:'v5_roots_done',water:'v5_water_done',flight:'v5_flight_done'};if(cues[event.id])audio.speak(cues[event.id]);experience?.showDiscovery({title:event.title+' · 回响归来',text:'这片土地记住了你的行动。器物与考据已收入记忆手册。'});updateQuest();persist();return;}
