function safePotteryCamera(){
 const pose=pottery.cameraPose(camera.aspect),colliders=[...(forest.cameraColliders||[]),...(traversal.cameraColliders||[]),...(adventure.cameraColliders||[])].filter(o=>{for(let n=o;n;n=n.parent)if(!n.visible)return false;return true;});
 function clampSight(end){const dir=end.clone().sub(pose.target),length=dir.length();ray.set(pose.target,dir.normalize());ray.far=length;const hit=cameraClearance.first(ray,colliders);return {end:hit?pose.target.clone().addScaledVector(dir,Math.max(.85,hit.distance-.22)):end,distance:hit?hit.distance:length};}
 let chosen=clampSight(pose.position);if(chosen.distance<2.1){const raised=clampSight(pose.position.clone().add(new THREE.Vector3(0,1.15,0)));if(raised.distance>chosen.distance)chosen=raised;}
 pose.position.copy(chosen.end);pose.position.y=Math.max(pose.position.y,traversal.sample(pose.position).groundHeight+.3);return pose;
}
