function applyMomentCamera(shot){
 if(!shot)return;
 const target=cameraTarget.clone().lerp(shot.target,shot.weight),end=camera.position.clone().lerp(shot.position,shot.weight);
 // The rebirth focus lies inside its subject tree. Do not treat that subject as
 // an obstruction along the viewing ray; all other world collision still applies.
 const colliders=visibleCameraColliders().filter(o=>shot.id!=='rebirth'||o.userData.cameraSubject!=='rebirth-root');
 const path=end.clone().sub(target),length=path.length();
 if(length>.001){ray.set(target,path.normalize());ray.far=length;const hit=cameraClearance.first(ray,colliders);if(hit)end.copy(target).addScaledVector(path,Math.max(.65,hit.distance-.3));}
 const surface=traversal.sample(end);end.y=Math.max(end.y,(surface.terrainHeight??surface.groundHeight)+.3);cameraClearance.constrain(camera,target,colliders,end);const fov=THREE.MathUtils.lerp(camera.fov,shot.fov,shot.weight);
 if(!cameraClearance.isUsableShot(camera,end,target,position,fov)){director.reset();activeShot=null;return;}
 camera.position.copy(end);camera.lookAt(target);camera.fov=fov;camera.updateProjectionMatrix();
}
function headingAt(distance){const a=forest.sample(distance),b=forest.sample(Math.min(forest.length,distance+1));return Math.atan2(-(b.x-a.x),-(b.z-a.z));}
